package dragonboat

import (
	"fmt"
	"sync"
	"testing"

	"github.com/lni/goutils/random"

	"github.com/lni/dragonboat/v3/client"
	"github.com/lni/dragonboat/v3/config"
	sm "github.com/lni/dragonboat/v3/statemachine"
)

// TestAssuranceNotifyCommitContract probes the two-phase ResultC contract for a
// proposal with commit notification enabled, and the terminal result for a
// proposal that passes its deadline before being applied.
func TestAssuranceNotifyCommitContract(t *testing.T) {
	cfg := config.Config{ClusterID: 1, NodeID: 1}
	q := newEntryQueue(8, 0)
	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	p := newPendingProposal(cfg, true, pool, q)
	s := client.NewNoOPSession(1, random.LockGuardedRand)

	req, err := p.propose(s, []byte("data"), 5)
	if err != nil {
		t.Fatalf("propose failed: %v", err)
	}
	key := req.key
	p.committed(s.ClientID, s.SeriesID, key)
	select {
	case r := <-req.committedC:
		fmt.Printf("CA_EVENT {\"event\":\"phase\",\"got\":%q}\n", r.code.String())
	default:
		fmt.Printf("CA_EVENT {\"event\":\"phase\",\"got\":\"none\"}\n")
	}
	p.applied(s.ClientID, s.SeriesID, key, sm.Result{Value: 7}, false)
	select {
	case r := <-req.CompletedC:
		fmt.Printf("CA_EVENT {\"event\":\"applied\",\"got\":%q}\n", r.code.String())
	default:
		fmt.Printf("CA_EVENT {\"event\":\"applied\",\"got\":\"none\"}\n")
	}

	req2, err := p.propose(s, []byte("late"), 3)
	if err != nil {
		t.Fatalf("second propose failed: %v", err)
	}
	p.tick(10)
	p.applied(s.ClientID, s.SeriesID, req2.key, sm.Result{Value: 8}, false)
	select {
	case r := <-req2.CompletedC:
		fmt.Printf("CA_EVENT {\"event\":\"late\",\"got\":%q}\n", r.code.String())
	default:
		fmt.Printf("CA_EVENT {\"event\":\"late\",\"got\":\"none\"}\n")
	}
	select {
	case <-req2.committedC:
		fmt.Printf("CA_EVENT {\"event\":\"late_commit\",\"got\":\"value\"}\n")
	default:
		fmt.Printf("CA_EVENT {\"event\":\"late_commit\",\"got\":\"none\"}\n")
	}
}

package rsm

import (
	"fmt"
	"testing"

	sm "github.com/lni/dragonboat/v3/statemachine"
)

// TestAssuranceSessionExactlyOnce probes the session decision logic that
// prevents a retried proposal from updating the state machine twice.
func TestAssuranceSessionExactlyOnce(t *testing.T) {
	ds := NewSessionManager()
	ds.RegisterClientID(42)
	s, ok := ds.ClientRegistered(42)
	if !ok {
		t.Fatalf("session not registered")
	}
	ds.UpdateRespondedTo(s, 0)
	_, responded, toUpdate := ds.UpdateRequired(s, 1)
	fmt.Printf("CA_EVENT {\"event\":\"first\",\"responded\":%t,\"update\":%t}\n", responded, toUpdate)
	ds.AddResponse(s, 1, sm.Result{Value: 9})
	v, responded, toUpdate := ds.UpdateRequired(s, 1)
	fmt.Printf("CA_EVENT {\"event\":\"retry_unacked\",\"responded\":%t,\"update\":%t,\"stored\":%d}\n", responded, toUpdate, v.Value)
	ds.UpdateRespondedTo(s, 1)
	_, responded, toUpdate = ds.UpdateRequired(s, 1)
	fmt.Printf("CA_EVENT {\"event\":\"retry_acked\",\"responded\":%t,\"update\":%t}\n", responded, toUpdate)
}

package rsm

import (
	"fmt"
	"testing"

	sm "github.com/lni/dragonboat/v3/statemachine"
)

// TestAssuranceSessionEviction probes which client session the LRU manager
// keeps when the configured capacity is exceeded, and what a client whose
// session was evicted observes when it asks for its stored result.
func TestAssuranceSessionEviction(t *testing.T) {
	l := newLRUSession(2)
	for _, id := range []uint64{11, 22, 33} {
		l.addSession(RaftClientID(id), *newSession(RaftClientID(id)))
		s, ok := l.getSession(RaftClientID(id))
		if !ok {
			t.Fatalf("session %d missing right after add", id)
		}
		s.addResponse(1, sm.Result{Value: id})
	}
	for _, id := range []uint64{11, 22, 33} {
		s, ok := l.getSession(RaftClientID(id))
		kept := ok && s != nil
		var stored uint64
		if ok && s != nil {
			if v, has := s.getResponse(1); has {
				stored = v.Value
			}
		}
		fmt.Printf("CA_EVENT {\"event\":\"session\",\"client\":%d,\"kept\":%t,\"stored\":%d}\n", id, kept, stored)
	}
}

package raft

import (
	"fmt"
	"testing"

	pb "github.com/lni/dragonboat/v3/raftpb"
)

// TestAssuranceSavedIndexAfterTruncation checks the in-memory saved-index
// accounting when a conflicting append replaces already-persisted entries.
func TestAssuranceSavedIndexAfterTruncation(t *testing.T) {
	l := newEntryLog(NewTestLogDB(), nil)
	l.append([]pb.Entry{
		{Index: 1, Term: 1}, {Index: 2, Term: 1}, {Index: 3, Term: 1}, {Index: 4, Term: 1},
	})
	l.commitUpdate(pb.UpdateCommit{StableLogTo: 4, StableLogTerm: 1})
	before := l.entriesToSave()
	l.tryAppend(2, []pb.Entry{{Index: 3, Term: 2}, {Index: 4, Term: 2}})
	after := l.entriesToSave()
	firstBefore := uint64(0)
	if len(before) > 0 {
		firstBefore = before[0].Index
	}
	firstAfter := uint64(0)
	if len(after) > 0 {
		firstAfter = after[0].Index
	}
	fmt.Printf("CA_EVENT {\"event\":\"save_range\",\"before_first\":%d,\"before_len\":%d,\"after_first\":%d,\"after_len\":%d,\"last_index\":%d,\"last_term\":%d}\n",
		firstBefore, len(before), firstAfter, len(after), l.lastIndex(), l.lastTerm())
}

package dragonboat

import (
	"fmt"
	"testing"

	"github.com/lni/dragonboat/v3/config"
	"github.com/lni/dragonboat/v3/internal/rsm"
	"github.com/lni/dragonboat/v3/internal/vfs"
)

// assuranceClusterInfoNode builds a node that carries the role flag a witness
// node is started with and a local state machine whose only use here is to
// report the state machine type. The raft peer is left nil, so the leader flag
// is reported as not leader.
func assuranceClusterInfoNode(t *testing.T, isWitness bool) *node {
	t.Helper()
	fs := vfs.GetTestFS()
	cfg := config.Config{ClusterID: 1, NodeID: 2, IsWitness: isWitness}
	n := &node{
		clusterID:    1,
		nodeID:       2,
		config:       cfg,
		initializedC: make(chan struct{}),
	}
	n.sm = rsm.NewStateMachine(
		rsm.NewNativeSM(cfg, &rsm.InMemStateMachine{}, nil),
		nil, cfg, &testDummyNodeProxy{}, fs)
	return n
}

// TestAssuranceClusterInfoWitnessFlag checks whether the per-cluster summary
// returned to a client reports a witness node as a witness. node.getClusterInfo
// rebuilds a ClusterInfo from the atomic record that node.notifyConfigChange
// stores; that record carries both the observer and the witness flag computed
// from the replicated membership. The witness case stores exactly such a
// record on a node whose own config says it is a witness, and the observer case
// stores an equivalent record for an observer as a control.
func TestAssuranceClusterInfoWitnessFlag(t *testing.T) {
	witness := assuranceClusterInfoNode(t, true)
	witness.clusterInfo.Store(&ClusterInfo{
		ClusterID:         1,
		NodeID:            2,
		IsLeader:          false,
		IsObserver:        false,
		IsWitness:         true,
		ConfigChangeIndex: 7,
		Nodes:             map[uint64]string{1: "a1", 2: "a2", 3: "a3"},
	})
	wci := witness.getClusterInfo()
	fmt.Printf("CA_EVENT {\"event\":\"witness_record\",\"stored_is_witness\":%t,\"node_config_is_witness\":%t,\"reported_is_witness\":%t,\"reported_is_observer\":%t,\"config_index\":%d,\"node_count\":%d,\"pending\":%t}\n",
		true, witness.isWitness(), wci.IsWitness, wci.IsObserver,
		wci.ConfigChangeIndex, len(wci.Nodes), wci.Pending)

	observer := assuranceClusterInfoNode(t, false)
	observer.clusterInfo.Store(&ClusterInfo{
		ClusterID:         1,
		NodeID:            2,
		IsLeader:          false,
		IsObserver:        true,
		IsWitness:         false,
		ConfigChangeIndex: 9,
		Nodes:             map[uint64]string{1: "a1", 2: "a2"},
	})
	oci := observer.getClusterInfo()
	fmt.Printf("CA_EVENT {\"event\":\"observer_record\",\"stored_is_observer\":%t,\"reported_is_observer\":%t,\"reported_is_witness\":%t,\"config_index\":%d,\"node_count\":%d,\"pending\":%t}\n",
		true, oci.IsObserver, oci.IsWitness,
		oci.ConfigChangeIndex, len(oci.Nodes), oci.Pending)

	pending := assuranceClusterInfoNode(t, true)
	pci := pending.getClusterInfo()
	fmt.Printf("CA_EVENT {\"event\":\"pending_record\",\"node_config_is_witness\":%t,\"reported_is_witness\":%t,\"pending\":%t,\"config_index\":%d}\n",
		pending.isWitness(), pci.IsWitness, pci.Pending, pci.ConfigChangeIndex)
}

package raft

import (
	"fmt"
	"testing"

	pb "github.com/lni/dragonboat/v3/raftpb"
)

func TestAssuranceReadIndexDiscardedOnStepDown(t *testing.T) {
	r := newTestRaft(1, []uint64{1, 2, 3}, 10, 1, NewTestLogDB())
	r.becomeCandidate()
	r.becomeLeader()
	r.remotes[2].match = r.log.lastIndex()
	committed := r.tryCommit()
	atTerm := r.hasCommittedEntryAtCurrentTerm()
	r.Handle(pb.Message{From: 1, To: 1, Type: pb.ReadIndex, Hint: 4242, HintHigh: 77})
	registered := r.readIndex.hasPendingRequest()
	fmt.Printf("CA_EVENT {\"event\":\"registered\",\"node\":1,\"committed\":%t,\"at_term\":%t,\"registered\":%t}\n", committed, atTerm, registered)
	r.Handle(pb.Message{From: 1, To: 1, Type: pb.CheckQuorum})
	stillLeader := r.isLeader()
	dropped := len(r.droppedReadIndexes)
	pending := r.readIndex.hasPendingRequest()
	fmt.Printf("CA_EVENT {\"event\":\"step_down\",\"node\":1,\"still_leader\":%t,\"dropped\":%d,\"pending\":%t}\n", stillLeader, dropped, pending)
	before := len(r.readyToRead)
	r.Handle(pb.Message{From: 2, To: 1, Term: r.term, Type: pb.HeartbeatResp, Hint: 4242, HintHigh: 77})
	added := len(r.readyToRead) - before
	fmt.Printf("CA_EVENT {\"event\":\"stale_resp\",\"node\":1,\"ready_added\":%d}\n", added)
	if stillLeader {
		t.Fatalf("leader did not step down")
	}
	if dropped != 0 {
		t.Fatalf("step down reported dropped read contexts: %d", dropped)
	}
	if pending {
		t.Fatalf("read context survived step down")
	}
	if added != 0 {
		t.Fatalf("stale response added ready to read entries: %d", added)
	}
}

